    const nonNull = values.filter(v => v !== null && v !== undefined);
    const hasString = nonNull.some(v => typeof v === 'string');
    const hasBool = nonNull.some(v => typeof v === 'boolean');
    const hasNumber = nonNull.some(v => typeof v === 'number');

    const uniq = Array.from(new Set(values.map(v => (v === null || v === undefined ? missingLabel : v))));
