    for (let i = 1; i < data.length; i++) {
        const row = document.createElement('tr');
        data[i].forEach(cell => {
            const td = document.createElement('td');
            td.textContent = cell;
            row.appendChild(td);
        });
        tbody.appendChild(row);
    }
    table.appendChild(tbody);

    // Add table to a temporary container
    const container = document.createElement('div');
    container.appendChild(table);

    // Initialize table filter
    const tf = new TableFilter(container, {
        base_path: 'https://unpkg.com/tablefilter@latest/dist/tablefilter/', // CDN path
        col_0: 'none', // Default: no filter on first column
