        btn_reset: false,
        loader: false,
        mark_active_columns: true,
        highlight_keywords: true,
        no_results_message: true,
        col_types: [], // We'll set this dynamically
        extensions: [{
            name: 'sort'
        }]
    });

    // Initialize the filter
    tf.init();

    // Configure filters based on conditions
    const headers = data[0];

    // First, set all columns to 'none' (no filter)
    headers.forEach((header, index) => {
        tf.setFilterValue(index, '');
        tf.setFilterType(index, 'none');
    });

    // Apply each condition
    conditions.forEach(condition => {
        const columnIndex = headers.indexOf(condition.column);

        if (columnIndex === -1) {
            console.warn(`Column "${condition.column}" not found in headers`);
            return;
        }

        // Map operator to table-filter filter type
        let filterType;
        switch(condition.operator) {
            case 'equals':
                filterType = 'input';
                tf.setFilterValue(columnIndex, condition.value);
                break;
            case 'contains':
                filterType = 'input';
                tf.setFilterValue(columnIndex, condition.value);
                break;
            case 'startsWith':
                filterType = 'input';
                tf.setFilterValue(columnIndex, condition.value + '*');
                break;
            case 'endsWith':
                filterType = 'input';
                tf.setFilterValue(columnIndex, '*' + condition.value);
                break;
            case 'greater':
                filterType = 'input';
                tf.setFilterValue(columnIndex, '>' + condition.value);
                break;
            case 'less':
                filterType = 'input';
                tf.setFilterValue(columnIndex, '<' + condition.value);
                break;
            case 'between':
                filterType = 'input';
                tf.setFilterValue(columnIndex, condition.value.join('-'));
                break;
            default:
                filterType = 'input';
                tf.setFilterValue(columnIndex, condition.value);
        }

        tf.setFilterType(columnIndex, filterType);
    });

    // Apply filters
    tf.filter();

    // Extract filtered data back to 2D array
    const filteredData = [headers]; // Start with headers

    // Get visible rows
    const visibleRows = tf.getValidRows();
    visibleRows.forEach(rowIndex => {
        // Skip header row (index 0)
        if (rowIndex > 0 && rowIndex < data.length) {
            filteredData.push(data[rowIndex]);
        }
    });

    // Clean up
    tf.destroy();
    container.remove();

    return filteredData;
}

