 *     g: x - y
 *   }),
 *   0.5, 0.5
 * );
 * console.log(result); // { x: ~0.707, y: ~0.707, iterations: ..., converged: true }
 */
function solveCoupledEquations(equationSystem, x0, y0, options = {}) {
  // Set default options
  const tolerance = options.tolerance || 1e-6;
  const maxIterations = options.maxIterations || 100;

  // Initialize variables
  let x = x0;
  let y = y0;
  let iterations = 0;
  let converged = false;

  // Numerical differentiation step size
  const h = 1e-8;

  // Newton-Raphson method for coupled equations
  for (let i = 0; i < maxIterations; i++) {
    // Evaluate the system at current point
    const current = equationSystem({ x, y });
    const f = current.f;
    const g = current.g;

    // Check convergence
    const residual = Math.sqrt(f * f + g * g);
    if (residual < tolerance) {
      converged = true;
      iterations = i;
      break;
    }

    // Compute Jacobian matrix using numerical differentiation
    const fxPlusDelta = equationSystem({ x: x + h, y }).f;
    const fx = (fxPlusDelta - f) / h;

    const fyPlusDelta = equationSystem({ x, y: y + h }).f;
    const fy = (fyPlusDelta - f) / h;

    const gxPlusDelta = equationSystem({ x: x + h, y }).g;
    const gx = (gxPlusDelta - g) / h;

    const gyPlusDelta = equationSystem({ x, y: y + h }).g;
    const gy = (gyPlusDelta - g) / h;

