function getMaxPerGroup(data, groupByColumn, maxColumn) {
  // Validate inputs
  if (!Array.isArray(data) || data.length === 0) {
    return [];
  }

  if (!groupByColumn || !maxColumn) {
    throw new Error('groupByColumn and maxColumn parameters are required');
