  for (const row of data) {
    if (!(groupByColumn in row)) {
      throw new Error(`Column "${groupByColumn}" not found in data`);
    }
    if (!(maxColumn in row)) {
      throw new Error(`Column "${maxColumn}" not found in data`);
    }

    const groupKey = row[groupByColumn];

    if (!grouped[groupKey]) {
      grouped[groupKey] = [];
    }
    grouped[groupKey].push(row);
