 * Given seqA = [a1, a2, ..., ak] and seqB = [b1, b2, ..., bk],
 * where each ai is a vector of length m and each bi is a vector of length n,
 * this function returns the m x n matrix:
 *   Sum_{i=1..k} (ai outer bi)
 *
 * It will attempt to use the "outer-product-sum" package if available;
 * otherwise it computes the sum directly.
 *
 * @param {Array<Array<number>>} seqA - Sequence of numeric vectors (length k).
 * @param {Array<Array<number>>} seqB - Sequence of numeric vectors (length k).
 * @returns {Array<Array<number>>} - m x n matrix (array of m rows, each row an array of n numbers).
 * @throws {TypeError} if arguments are not arrays of numeric arrays or lengths don't match.
 */
function sumOuterProducts(seqA, seqB) {
  // Basic validation
  if (!Array.isArray(seqA) || !Array.isArray(seqB)) {
    throw new TypeError('Both arguments must be arrays of numeric arrays.');
  }
  const k = seqA.length;
  if (k !== seqB.length) {
    throw new TypeError('Sequences must have the same number of vectors.');
  }
  if (k === 0) {
    // Nothing to sum => return empty matrix
    return [];
  }

  // Ensure vectors and determine dimensions m and n
  const firstA = seqA[0];
  const firstB = seqB[0];
  if (!Array.isArray(firstA) || !Array.isArray(firstB)) {
    throw new TypeError('Each element of sequences must be an array of numbers.');
  }
  const m = firstA.length;
  const n = firstB.length;

  // Validate all vectors and numeric entries
  for (let i = 0; i < k; i++) {
    if (!Array.isArray(seqA[i]) || seqA[i].length !== m) {
      throw new TypeError(`All vectors in seqA must be arrays of length ${m} (mismatch at index ${i}).`);
    }
    if (!Array.isArray(seqB[i]) || seqB[i].length !== n) {
      throw new TypeError(`All vectors in seqB must be arrays of length ${n} (mismatch at index ${i}).`);
    }
    for (let j = 0; j < m; j++) {
      if (typeof seqA[i][j] !== 'number' || !isFinite(seqA[i][j])) {
        throw new TypeError(`Non-finite number found in seqA at [${i}][${j}].`);
      }
    }
    for (let j = 0; j < n; j++) {
      if (typeof seqB[i][j] !== 'number' || !isFinite(seqB[i][j])) {
