        const r = l + 1;
        let smallest = p;
        if (l < heap.length && heap[l].val < heap[smallest].val) smallest = l;
        if (r < heap.length && heap[r].val < heap[smallest].val) smallest = r;
        if (smallest === p) break;
        const tmp = heap[p]; heap[p] = heap[smallest]; heap[smallest] = tmp;
        p = smallest;
      }
    }
  }

  // Extract heap entries and sort descending by value
  const results = new Array(heap.length);
  for (let i = heap.length - 1; i >= 0; i--) {
    results[i] = heapPop();
  }
  // results currently in ascending order of val (because popped from min-heap),
  // so reverse to descending
  results.reverse();
  return results.map(e => e.idx);
}

