function centerPad(text, totalLength, paddingChar = ' ') {
  // Validate inputs
  if (typeof text !== 'string') {
    throw new TypeError('Text must be a string');
  }

  if (typeof totalLength !== 'number' || totalLength < 0 || !Number.isInteger(totalLength)) {
    throw new TypeError('Total length must be a non-negative integer');
  }

  if (typeof paddingChar !== 'string' || paddingChar.length !== 1) {
    throw new TypeError('Padding character must be a single character string');
  }

  // If the text is already longer than or equal to the desired length, return it as-is
  if (text.length >= totalLength) {
    return text;
  }

  // Calculate padding needed on each side
  const totalPadding = totalLength - text.length;
  const leftPadding = Math.floor(totalPadding / 2);
  const rightPadding = totalLength - text.length - leftPadding;

  // Create the padded string
  const leftPad = paddingChar.repeat(leftPadding);
  const rightPad = paddingChar.repeat(rightPadding);

  return leftPad + text + rightPad;
}

